<?php
namespace App\Services;
use App\Exceptions\BookingConflictException; use App\Models\Availability; use App\Models\BlockedTime; use App\Models\Provider;
class ProviderScheduleService { public function __construct(private SlotCacheService $cache){} public function createAvailability(Provider $provider,array $data): Availability { $overlap=$provider->availabilities()->where('day_of_week',$data['day_of_week'])->where('start_time','<',$data['end_time'])->where('end_time','>',$data['start_time'])->exists(); if($overlap){throw new BookingConflictException('This availability overlaps an existing availability.');} $model=$provider->availabilities()->create($data);$this->cache->invalidate($provider->id);return $model; } public function createBlockedTime(Provider $provider,array $data): BlockedTime { $overlap=$provider->blockedTimes()->where('starts_at','<',$data['ends_at'])->where('ends_at','>',$data['starts_at'])->exists(); if($overlap){throw new BookingConflictException('This blocked period overlaps an existing blocked period.');} $model=$provider->blockedTimes()->create($data);$this->cache->invalidate($provider->id);return $model; } public function deleteAvailability(Availability $availability): void {$id=$availability->provider_id;$availability->delete();$this->cache->invalidate($id);} public function deleteBlockedTime(BlockedTime $blocked): void {$id=$blocked->provider_id;$blocked->delete();$this->cache->invalidate($id);} }
